import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The drafter's open-question marker. Resolving an item means replacing the marker with the answer. */
const NEEDS_HUMAN_INPUT = /NEEDS HUMAN INPUT/;
/** A bulleted field with a bold label: `- **Tier**: limited` or `- **Tier:** limited`. */
const FIELD_LINE = /^(\s*)[-*]\s+\*\*([^*]+?)\*\*(.*)$/;

interface Section {
  heading: string;
  body: string;
}

interface Field {
  label: string;
  /** The field line as written, trimmed. */
  line: string;
  /** Index of the field line within the subsection body. */
  lineIndex: number;
  /** The inline value plus any indented lines under the field (tables, nested bullets). */
  value: string;
  answered: boolean;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

/** Index of the first colon outside parentheses, or -1. Skips hints like "(name + date; otherwise ...)". */
function separatorIndex(text: string): number {
  let depth = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '(') depth += 1;
    else if (text[i] === ')') depth = Math.max(0, depth - 1);
    else if (text[i] === ':' && depth === 0) return i;
  }
  return -1;
}

/** Real content has at least one letter or digit; bare bullets, pipes, and punctuation do not count. */
function hasContent(text: string): boolean {
  return /[\p{L}\p{N}]/u.test(text);
}

/**
 * Parses the bold-labelled fields of a subsection. A field's answer is its inline value plus
 * any lines indented deeper than the field line (blank lines in between are allowed).
 */
function parseFields(body: string): Field[] {
  const lines = body.split(/\r?\n/);
  const fields: Field[] = [];
  let open: { indent: number; inline: string; nested: string[] } | null = null;
  let openField: Field | null = null;

  const close = () => {
    if (!openField || !open) return;
    const nested = open.nested.join('\n');
    openField.value = [open.inline.trim(), nested].filter(Boolean).join('\n');
    openField.answered = hasContent(open.inline) || hasContent(nested);
    open = null;
    openField = null;
  };

  lines.forEach((line, lineIndex) => {
    if (line.trim() === '') return;
    const indent = line.length - line.trimStart().length;
    if (open && indent > open.indent) {
      open.nested.push(line.trim());
      return;
    }
    close();
    const m = line.match(FIELD_LINE);
    if (!m) return;

    // `**Tier:**` puts the colon inside the bold label; `**Tier**:` puts it after.
    const rawLabel = m[2].trim();
    const labelHasColon = rawLabel.endsWith(':');
    const rest = m[3];
    const inline = labelHasColon
      ? rest
      : rest.slice(separatorIndex(rest) + 1 || 0);
    const field: Field = {
      label: rawLabel.replace(/:$/, '').trim(),
      line: line.trim(),
      lineIndex,
      value: '',
      answered: false
    };
    fields.push(field);
    openField = field;
    open = { indent, inline, nested: [] };
  });
  close();
  return fields;
}

function extractTier(body: string, fields: Field[]): RiskTier | null {
  // An explicit "Tier" field is authoritative - a fallback body search would pick up
  // incidental mentions like "(tier below high)" in the sign-off.
  const tierField = fields.find((f) => /^tier$/i.test(f.label));
  const text = tierField ? tierField.value : body;
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
  if (found.length === 1) return found[0];
  if (found.length > 1) {
    // Ambiguous mention; prefer the value after a colon.
    const afterColon = cleaned.split(':').slice(1).join(':');
    const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
    if (inValue.length === 1) return inValue[0];
  }
  return null;
}

/** The subsection text without fields that were never answered. */
function answeredText(body: string, fields: Field[]): string {
  const unanswered = new Set(fields.filter((f) => !f.answered).map((f) => f.lineIndex));
  return body
    .split(/\r?\n/)
    .filter((_, i) => !unanswered.has(i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
