import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** The drafter's open-question marker. Resolving an item means replacing the marker with the answer. */
const NEEDS_HUMAN_INPUT = /NEEDS HUMAN INPUT/;
/** A bulleted field with a bold label: `- **Tier**: limited` or `- **Tier:** limited`. */
const FIELD_LINE = /^(\s*)[-*]\s+\*\*([^*]+?)\*\*(.*)$/;

interface Section {
  heading: string;
  body: string;
}

interface Field {
  label: string;
  /** The field line as written, trimmed. */
  line: string;
  /** Index of the field line within the subsection body. */
  lineIndex: number;
  /** The inline value plus any indented lines under the field (tables, nested bullets). */
  value: string;
  answered: boolean;
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

/** Index of the first colon outside parentheses, or -1. Skips hints like "(name + date; otherwise ...)". */
function separatorIndex(text: string): number {
  let depth = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '(') depth += 1;
    else if (text[i] === ')') depth = Math.max(0, depth - 1);
    else if (text[i] === ':' && depth === 0) return i;
  }
  return -1;
}

/** Real content has at least one letter or digit; bare bullets, pipes, and punctuation do not count. */
function hasContent(text: string): boolean {
  return /[\p{L}\p{N}]/u.test(text);
}

/**
 * Parses the bold-labelled fields of a subsection. A field's answer is its inline value plus
 * any lines indented deeper than the field line (blank lines in between are allowed).
 */
function parseFields(body: string): Field[] {
  const lines = body.split(/\r?\n/);
  const parsed: Array<{ field: Field; inline: string; nested: string[]; indent: number }> = [];
  let current: (typeof parsed)[number] | null = null;

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    const line = lines[lineIndex];
    if (line.trim() === '') continue;
    const indent = line.length - line.trimStart().length;
    if (current && indent > current.indent) {
      current.nested.push(line.trim());
      continue;
    }
    current = null;
    const m = line.match(FIELD_LINE);
    if (!m) continue;

    // `**Tier:**` puts the colon inside the bold label; `**Tier**:` puts it after the label.
    const labelHasColon = m[2].trim().endsWith(':');
    const rest = m[3];
    const sep = labelHasColon ? -1 : separatorIndex(rest);
    current = {
      field: {
        label: m[2].replace(/:$/, '').trim(),
        line: line.trim(),
        lineIndex,
        value: '',
        answered: false
      },
      inline: sep === -1 ? rest : rest.slice(sep + 1),
      nested: [],
      indent
    };
    parsed.push(current);
  }

  return parsed.map(({ field, inline, nested }) => {
    const nestedText = nested.join('\n');
    field.value = [inline.trim(), nestedText].filter(Boolean).join('\n');
    field.answered = hasContent(inline) || hasContent(nestedText);
    return field;
  });
}

function extractTier(body: string, fields: Field[]): RiskTier | null {
  // An explicit "Tier" field is authoritative - a fallback body search would pick up
  // incidental mentions like "(tier below high)" in the sign-off.
  const tierField = fields.find((f) => /^tier$/i.test(f.label));
  const text = tierField ? tierField.value : body;
  // Skip the template's enum hint "(prohibited / high / limited / minimal)".
  const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
  const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
  if (found.length === 1) return found[0];
  if (found.length > 1) {
    // Ambiguous mention; prefer the value after a colon.
    const afterColon = cleaned.split(':').slice(1).join(':');
    const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
    if (inValue.length === 1) return inValue[0];
  }
  return null;
}

/** The subsection text without fields that were never answered. */
function answeredText(body: string, fields: Field[]): string {
  const unanswered = new Set(fields.filter((f) => !f.answered).map((f) => f.lineIndex));
  return body
    .split(/\r?\n/)
    .filter((_, i) => !unanswered.has(i))
    .join('\n')
    .trim();
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const fields = parseFields(body);
    const answered = answeredText(body, fields);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    for (const line of body.split(/\r?\n/).filter((l) => NEEDS_HUMAN_INPUT.test(l))) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unresolved NEEDS HUMAN INPUT in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    for (const field of fields.filter((f) => !f.answered)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${field.line}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body, fields);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoffLine = body
          .split(/\r?\n/)
          .find((l) => /sign[- ]?off/i.test(l) && !EMPTY_FIELD.test(l));
        const signoffValue = signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
        if (!signoffValue || /not\s+required/i.test(signoffValue)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

