82	function separatorIndex(text: string): number {
83	  let depth = 0;
84	  for (let i = 0; i < text.length; i += 1) {
85	    if (text[i] === '(') depth += 1;
86	    else if (text[i] === ')') depth = Math.max(0, depth - 1);
